{
  "metric": "cogs",
  "periodA": "2026-08",
  "periodB": "2026-09",
  "answerable": true,
  "missingData": null,
  "hypotheses": [
    {
      "id": "h1",
      "driverType": "supplier_price",
      "text": "Vendor VEND-SNC invoiced above contracted unit price for specific SKUs in September, creating excess COGS.",
      "checks": "SELECT pl.vendor_id, v.vendor_name, SUM(pl.amount_cad - (pl.qty * pl.contract_unit_price * pl.fx_rate)) AS excess_cad FROM lightning.metastore.finmozg.finance_usl.purchase_line pl JOIN lightning.metastore.finmozg.finance_usl.vendor v ON pl.vendor_id = v.vendor_id WHERE pl.period = '2026-09' AND pl.vendor_id = 'VEND-SNC' GROUP BY pl.vendor_id, v.vendor_name HAVING excess_cad > 0"
    },
    {
      "id": "h2",
      "driverType": "supplier_price",
      "text": "Other vendors also invoiced above contracted unit price in September, contributing to the COGS increase.",
      "checks": "SELECT pl.vendor_id, v.vendor_name, SUM(pl.amount_cad - (pl.qty * pl.contract_unit_price * pl.fx_rate)) AS excess_cad FROM lightning.metastore.finmozg.finance_usl.purchase_line pl JOIN lightning.metastore.finmozg.finance_usl.vendor v ON pl.vendor_id = v.vendor_id WHERE pl.period = '2026-09' GROUP BY pl.vendor_id, v.vendor_name HAVING excess_cad > 0 ORDER BY excess_cad DESC"
    },
    {
      "id": "h3",
      "driverType": "volume",
      "text": "Total quantity purchased changed between August and September, affecting COGS.",
      "checks": "SELECT period, SUM(qty) AS total_qty FROM lightning.metastore.finmozg.finance_usl.purchase_line WHERE period IN ('2026-08','2026-09') GROUP BY period"
    },
    {
      "id": "h4",
      "driverType": "mix",
      "text": "The mix of purchased SKUs shifted toward higher‑cost items in September.",
      "checks": "SELECT pl.period, SUM(pl.qty * p.wholesale_price_cad) / SUM(pl.qty) AS weighted_avg_wholesale_price_cad FROM lightning.metastore.finmozg.finance_usl.purchase_line pl JOIN lightning.metastore.finmozg.finance_usl.product p ON pl.sku = p.sku WHERE pl.period IN ('2026-08','2026-09') GROUP BY pl.period"
    },
    {
      "id": "h5",
      "driverType": "fx",
      "text": "The USD/CAD rate changed the CAD cost of USD‑denominated vendor invoices between August and September.",
      "checks": "SELECT period, AVG(fx_rate) AS avg_fx_rate FROM lightning.metastore.finmozg.finance_usl.purchase_line WHERE currency = 'USD' AND period IN ('2026-08','2026-09') GROUP BY period"
    },
    {
      "id": "h6",
      "driverType": "booking_error",
      "text": "Duplicate AP invoices were booked for the same vendor invoice number in September, inflating costs.",
      "checks": "SELECT vendor_invoice_no, COUNT(*) AS invoice_cnt FROM lightning.metastore.finmozg.finance_usl.vendor_bill WHERE period = '2026-09' GROUP BY vendor_invoice_no HAVING COUNT(*) > 1"
    },
    {
      "id": "h7",
      "driverType": "opex",
      "text": "Marketing expense (account 6100) increased significantly between August and September, a possible alternative explanation for overall expense rise.",
      "checks": "SELECT period, amount_cad FROM lightning.metastore.finmozg.finance_usl.gl_balance WHERE account_code = '6100' AND period IN ('2026-08','2026-09')"
    }
  ]
}
